-- Alta de catalogo: canciones y albumes que faltaban de los clientes de MALO.
--
-- Research del 2 sep 2026. Metodo: se parte del enlace de Spotify de cada ficha
-- de cliente; Spotify no expone la discografia sin API, asi que de su pagina se
-- saca el nombre exacto del artista y sus 10 top-tracks (embed), y con eso se
-- identifica al artista en Apple Music, cuyo catalogo si es consultable y no
-- fusiona homonimos. Los 13 artistas coinciden en 7-10 de esos 10 top-tracks.
-- (Deezer se descarto como fuente: mezcla artistas distintos bajo un mismo
-- perfil -- el «Nostos» de Deezer incluye discos de doom metal y temas en rumano,
-- y el «Sent» un album de gospel de 2011.)
--
-- Reglas aplicadas, todas con evidencia:
--   * DUEÑO del corte = primer nombre acreditado que sea cliente de MALO, dando
--     preferencia a los de categoria artista. Asi las colaboraciones entre gente
--     de la casa NO crean dos filas.
--   * PRODUCTORES (El WiWi, JOHNNYFUU, Virtual Flavor) no llevan fila propia:
--     entran en cancion_participantes con rol 'productor'. La app ya compone el
--     titulo publico con «prod. X» a partir de ahi.
--   * distribuidora: por artista, ADA si la fecha es posterior a su primer
--     release ADA ya cargado; Externa (fee 0) si es anterior. Para los artistas
--     sin catalogo ADA previo se deja VACIA a proposito -- no hay evidencia de
--     quien distribuye, y es un campo de un clic en la ficha.
--   * los cortes en los que el cliente aparece acreditado sobre un release de un
--     tercero entran como 'Colaboración', igual que se hizo con WINE (Yung Beef).
--   * reparto: si el corte es de un solo cliente, participante unico al 100%.
--     Si hay varios, TODOS entran al 0% -- el reparto lo decide Malo, y un 0
--     se ve en la app como «reparto pendiente» en vez de colar un porcentaje
--     inventado. No se toca cancion_ingresos: no hay liquidacion todavia.
--
-- SIN ISRC: la API de Deezer, que es de donde salian, nos esta limitando hoy.
-- Se rellenan luego con supabase/isrc-pendientes.sql sin tocar estas filas.
--
-- Idempotente: ids deterministas y se descarta por titulo lo que ya exista para
-- ese artista, asi que se puede ejecutar varias veces.

begin;

create temp table _nuevas (
  id text, titulo text, artista_id text, distribuidora text,
  fee_distribucion_pct numeric, mgmt_pct numeric, fecha_lanzamiento date,
  mixtape text, portada_url text, genero text, distribucion jsonb,
  notas text, sello text
) on commit drop;


create temp table _partes (cancion_id text, cliente_id text, nombre text, rol text, pct numeric) on commit drop;

-- fuera lo que ya exista en la app con ese titulo, de CUALQUIER artista (Malo
-- puede haber cargado mas mientras se hacia esto, y un corte del colectivo ya
-- vive bajo un solo dueno)
delete from _nuevas n using public.canciones c
 where lower(regexp_replace(c.titulo,'[^a-zA-Z0-9]','','g'))
     = lower(regexp_replace(n.titulo,'[^a-zA-Z0-9]','','g'));
delete from _partes p where not exists (select 1 from _nuevas n where n.id = p.cancion_id);

   fecha_lanzamiento, mixtape, portada_url, genero, distribucion, notas)
select id, titulo, artista_id, distribuidora, fee_distribucion_pct, mgmt_pct,
       fecha_lanzamiento, mixtape, portada_url, genero, distribucion, notas
from _nuevas
on conflict (id) do nothing;

select 'canp_'||substr(md5(p.cancion_id||p.cliente_id||p.rol),1,12),
       p.cancion_id, p.cliente_id, p.nombre, p.rol, p.pct
from _partes p
where exists (select 1 from public.canciones c where c.id = p.cancion_id)
on conflict (id) do nothing;

commit;

-- resumen
select c.nombre, count(*) canciones,
       count(*) filter (where k.distribuidora='ADA') ada,
       count(*) filter (where k.distribuidora='Externa') externa,
       count(*) filter (where k.distribuidora='') sin_confirmar,
       count(*) filter (where k.distribuidora='Colaboración') colabs,
       count(distinct nullif(k.mixtape,'')) releases
from public.canciones k join public.clientes c on c.id=k.artista_id
group by 1 order by 2 desc;
